insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_55_v1'
from (values
('127.315.d.1.A',3,'A new teacher notices constant headaches, trouble sleeping, and dread every Monday morning. These are common signs of:','["work-related stress", "improved wellness", "job satisfaction", "strong boundaries"]'::jsonb,0,'Physical and sleep symptoms often signal stress.','original'),
('127.315.d.1.A',4,'Which behavior most clearly shows that stress is turning into anxiety for a student teacher?','["Being excited about a field trip", "Persistent worry that interferes with sleep and concentration", "Occasional nervousness before a lesson that fades", "Feeling tired after a long day"]'::jsonb,1,'Anxiety is persistent and disrupts daily functioning.','original'),
('127.315.d.1.B',3,'A teacher decides not to check school email after 7 p.m. This is an example of:','["a discipline referral", "a grading policy", "a work-life boundary", "a lesson objective"]'::jsonb,2,'Boundaries protect personal time.','original'),
('127.315.d.1.B',4,'A teacher already overloaded is asked to chair a fourth committee. The healthiest response is to:','["accept and resent it silently", "accept and stop sleeping", "accept and skip lesson planning", "decline politely and explain current workload limits"]'::jsonb,3,'Saying no respectfully protects balance.','original'),
('127.315.d.1.C',3,'Which routine best supports a teacher''s long-term wellness?','["Regular exercise, sleep, and nutritious meals", "Relying on energy drinks", "Skipping lunch to grade", "Working through weekends"]'::jsonb,0,'Basic health habits sustain energy.','original'),
('127.315.d.1.C',4,'Using a planner to spread grading across the week helps a teacher manage:','["student attendance", "workload stress", "bus duty", "fire drills"]'::jsonb,1,'Planning prevents last-minute overload.','original'),
('127.315.d.2.A',3,'The common school movement, led by Horace Mann, promoted:','["private tutoring only", "education only for wealthy boys", "publicly funded schools open to all children", "ending public schooling"]'::jsonb,2,'Mann championed universal public education.','original'),
('127.315.d.2.A',4,'The 1954 Supreme Court decision in Brown v. Board of Education ruled that:','["teachers must be licensed", "school prayer was required", "states must fund private schools", "racially segregated public schools were unconstitutional"]'::jsonb,3,'Brown overturned separate-but-equal in schools.','original'),
('127.315.d.2.B',3,'Pedagogical knowledge is a teacher''s understanding of:','["how to teach effectively", "how to design buildings", "how to manage a school budget", "how to repair equipment"]'::jsonb,0,'Pedagogy is the art and science of teaching.','original'),
('127.315.d.2.B',4,'A teacher models a math step, guides practice, then has students work alone. This sequence is called:','["classroom rotation", "gradual release of responsibility", "summative testing", "random instruction"]'::jsonb,1,'I do, we do, you do.','original'),
('127.315.d.2.C',3,'Which is a quality of an effective school?','["Little teacher collaboration", "Unclear goals", "High expectations for all students", "Low attendance"]'::jsonb,2,'Effective schools expect success from everyone.','original'),
('127.315.d.2.C',4,'Schools with strong family and community engagement tend to see:','["less safe campuses", "lower graduation rates", "weaker teacher morale", "better student attendance and achievement"]'::jsonb,3,'Engagement supports student success.','original'),
('127.315.d.2.D',3,'A corporate trainer who teaches employees new software is working in:','["a non-traditional teaching setting", "a public elementary school", "a school board", "a state legislature"]'::jsonb,0,'Training careers exist outside schools.','original'),
('127.315.d.2.D',4,'Which job is a teaching and training career outside a school building?','["Bus mechanic", "Museum educator", "Crossing guard", "Cafeteria cashier"]'::jsonb,1,'Museums employ educators.','original'),
('127.315.d.2.E',3,'A statement of beliefs about the purpose of education and how students learn is a:','["lesson plan", "grade book", "philosophy of education", "hall pass"]'::jsonb,2,'A philosophy guides teaching decisions.','original'),
('127.315.d.2.E',4,'A teacher who believes students learn best by doing hands-on projects would most likely emphasize:','["silent lectures only", "copying notes", "memorizing lists", "experiential learning"]'::jsonb,3,'Experiential learning centers on doing.','original'),
('127.315.d.3.A',3,'Knowing that most 6-year-olds have short attention spans, a teacher plans:','["short activities with movement breaks", "a 90-minute lecture", "a silent two-hour test", "only independent reading"]'::jsonb,0,'Instruction should fit developmental level.','original'),
('127.315.d.3.A',4,'Piaget''s concrete operational stage suggests elementary students learn best with:','["only symbolic equations", "hands-on objects and real examples", "abstract philosophical debates", "only lectures"]'::jsonb,1,'Children this age reason about concrete things.','original'),
('127.315.d.3.B',3,'A teacher who gives immediate praise to strengthen desired behavior is applying:','["constructivist theory", "humanist theory", "behaviorist theory", "cognitive load theory"]'::jsonb,2,'Behaviorism uses reinforcement.','original'),
('127.315.d.3.B',4,'Vygotsky''s zone of proximal development describes tasks a learner can do:','["never, even with help", "alone without effort", "only after graduation", "with guidance but not yet alone"]'::jsonb,3,'The ZPD lies between independence and frustration.','original'),
('127.315.d.3.C',3,'Which teacher behavior best facilitates learning?','["Clearly explaining expectations and giving feedback", "Talking over students", "Changing rules daily", "Ignoring questions"]'::jsonb,0,'Clarity and feedback support learning.','original'),
('127.315.d.3.C',4,'Wait time of three to five seconds after asking a question helps because it:','["bores students", "gives students time to think and respond", "ends discussion", "signals the answer"]'::jsonb,1,'Pausing improves response quality.','original'),
('127.315.d.3.D',3,'Connecting a new concept to students'' prior knowledge makes instruction more:','["confusing", "optional", "meaningful", "expensive"]'::jsonb,2,'Prior knowledge anchors new learning.','original'),
('127.315.d.3.D',4,'Checking for understanding during a lesson, not only at the end, helps teachers:','["avoid grading", "skip planning", "reduce participation", "adjust instruction while it still matters"]'::jsonb,3,'Ongoing checks allow quick correction.','original'),
('127.315.d.3.E',3,'Before planning a unit, a teacher surveys students'' interests and reading levels. This is evaluating students'':','["backgrounds and strengths", "lunch accounts", "locker numbers", "bus routes"]'::jsonb,0,'Knowing learners guides planning.','original'),
('127.315.d.3.E',4,'A teacher learns that many students speak Spanish at home and adds bilingual vocabulary support. This shows planning that:','["replaces the TEKS", "builds on students'' language backgrounds", "lowers expectations", "ignores student diversity"]'::jsonb,1,'Assets-based planning uses home language.','original'),
('127.315.d.3.F',3,'Which action best builds a positive teacher-student relationship?','["Using sarcasm", "Favoring a few students", "Learning students'' names and showing interest in them", "Avoiding eye contact"]'::jsonb,2,'Respect and interest build rapport.','original'),
('127.315.d.3.F',4,'A teacher greets each student at the door every day. This routine helps establish:','["anonymity", "strict silence", "competition", "trust and a sense of belonging"]'::jsonb,3,'Daily greetings show students they matter.','original'),
('127.315.d.4.A',3,'Which stakeholder is most directly responsible for a school''s overall operations?','["The principal", "A classroom volunteer", "A vendor", "A student"]'::jsonb,0,'Principals lead the campus.','original'),
('127.315.d.4.A',4,'When a parent is upset about a grade, the best first step is to:','["avoid the parent", "listen calmly and acknowledge the concern", "defend the grade immediately", "end the meeting"]'::jsonb,1,'Listening de-escalates tension.','original'),
('127.315.d.4.B',3,'Inviting community members to speak to a class about their careers builds:','["testing windows", "school rivalries", "school-community partnerships", "grading policies"]'::jsonb,2,'Guest speakers connect schools and communities.','original'),
('127.315.d.4.B',4,'A school-business partnership that provides student internships benefits students by:','["reducing graduation", "limiting options", "replacing classes", "giving them real-world work experience"]'::jsonb,3,'Internships build career skills.','original'),
('127.315.d.4.C',3,'Under Texas law, a professional who suspects child abuse must report it within:','["48 hours", "two weeks", "the end of the school year", "30 days"]'::jsonb,0,'Professionals must report within 48 hours.','original'),
('127.315.d.4.C',4,'A teacher suspects a student is being abused. The teacher should report to:','["only the student''s friends", "the Texas Department of Family and Protective Services or law enforcement", "the student''s classmates", "a social media group"]'::jsonb,1,'Reports go to DFPS or police.','original'),
('127.315.d.5.A',3,'The TEKS tell teachers:','["which textbook to buy", "how to run bus routes", "what students should know and be able to do at each grade or course", "what salary to pay"]'::jsonb,2,'TEKS are the state standards.','original'),
('127.315.d.5.A',4,'A teacher starts unit planning with the TEKS and the end goal, then designs lessons. This approach is called:','["free-form teaching", "forward guessing", "random sequencing", "backward design"]'::jsonb,3,'Backward design starts with the desired results.','original'),
('127.315.d.5.B',3,'Teachers need strong knowledge of their subject so they can:','["explain concepts accurately and answer questions", "avoid planning", "limit questions", "skip assessments"]'::jsonb,0,'Content knowledge supports clear teaching.','original'),
('127.315.d.5.B',4,'A teacher who understands common student misconceptions in math can:','["reduce rigor", "anticipate and correct errors in thinking", "avoid hard topics", "hide mistakes"]'::jsonb,1,'Knowing misconceptions improves instruction.','original'),
('127.315.d.5.C',3,'Which is a component of an instructional plan?','["Bus routes and parking", "Athletic schedules", "Objectives, activities, materials, and assessment", "Hall passes, fire drills, and yearbooks"]'::jsonb,2,'Plans connect goals, tasks, and evidence.','original'),
('127.315.d.5.C',4,'The closure part of a lesson is designed to:','["introduce new homework only", "end class early", "grade papers", "help students summarize and reflect on the learning"]'::jsonb,3,'Closure consolidates learning.','original'),
('127.315.d.5.D',3,'Bloom''s taxonomy helps teachers plan by classifying:','["levels of thinking from remembering to creating", "bus routes", "student heights", "school budgets"]'::jsonb,0,'Bloom''s levels guide question and task design.','original'),
('127.315.d.5.D',4,'A teacher writes objectives that move from recalling facts to evaluating arguments. This follows:','["a bus schedule", "Bloom''s taxonomy", "a seating chart", "the school calendar"]'::jsonb,1,'Objectives climb the taxonomy.','original'),
('127.315.d.5.E',3,'Which is a measurable learning objective?','["Students will enjoy class", "Students will understand freedom", "Students will identify three causes of the American Revolution", "Students will appreciate history"]'::jsonb,2,'Measurable objectives name observable actions.','original'),
('127.315.d.5.E',4,'A short-term objective differs from a long-term objective because it:','["applies only to teachers", "takes years to achieve", "has no assessment", "can be reached within a lesson or a few days"]'::jsonb,3,'Short-term goals are quickly reachable.','original'),
('127.315.d.5.F',3,'A lesson plan should align the activity, the objective, and the:','["assessment", "parking rule", "lunch menu", "bus route"]'::jsonb,0,'Alignment connects teaching to evidence.','original'),
('127.315.d.5.F',4,'A teacher adds a vocabulary preview because the objective requires reading a complex text. This is aligning:','["lunch to recess", "instruction to the learning goal", "grades to attendance", "seating to height"]'::jsonb,1,'Supports are chosen to reach the goal.','original'),
('127.315.d.6.A',3,'A safe and effective classroom environment includes:','["unclear rules", "hidden hazards", "clear procedures and respectful interactions", "sarcastic comments"]'::jsonb,2,'Structure and respect support learning.','original'),
('127.315.d.6.A',4,'Posting emergency exit routes and practicing drills shows a teacher''s commitment to:','["grade inflation", "hall decoration", "lesson length", "physical safety"]'::jsonb,3,'Drills prepare students for emergencies.','original'),
('127.315.d.6.B',3,'Grouping students by shared skill gaps for a short mini-lesson is:','["flexible ability grouping", "random seating", "punishment", "permanent tracking"]'::jsonb,0,'Flexible groups change as needs change.','original'),
('127.315.d.6.B',4,'Which grouping strategy mixes strengths so students can support one another?','["Whole-class lecture", "Heterogeneous grouping", "Homogeneous grouping", "Individual detention"]'::jsonb,1,'Mixed groups let students learn from peers.','original'),
('127.315.d.6.C',3,'A teacher who arrives prepared, begins on time, and keeps materials ready is promoting:','["wasted time", "delays", "an efficient learning environment", "student confusion"]'::jsonb,2,'Preparation protects instructional time.','original'),
('127.315.d.6.C',4,'Using a bell-ringer activity helps students:','["socialize", "skip class", "delay work", "start learning immediately as class begins"]'::jsonb,3,'Warm-ups focus students quickly.','original'),
('127.315.d.6.D',3,'Before choosing a video for class, a teacher should check that it is:','["age-appropriate and aligned to the lesson", "popular online", "the funniest", "the longest available"]'::jsonb,0,'Materials must fit the audience and goal.','original'),
('127.315.d.6.D',4,'A text far above students'' reading level is likely to:','["increase motivation always", "frustrate students and limit comprehension", "require no support", "raise comprehension"]'::jsonb,1,'Too-hard text blocks understanding.','original'),
('127.315.d.6.E',3,'Which technique helps prevent misbehavior?','["Changing rules daily", "Waiting for problems", "Teaching and practicing procedures at the start of the year", "Ignoring routines"]'::jsonb,2,'Prevention beats correction.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_55_v1'
from (values
('127.315.d.6.E',4,'A teacher quietly moves closer to a talkative student without stopping the lesson. This technique is called:','["public reprimand", "removal", "detention", "proximity control"]'::jsonb,3,'Nearness redirects behavior quietly.','original'),
('127.315.d.6.F',3,'Two students argue over a seat. A teacher using mediation would:','["help each student state their view and find a solution", "punish both automatically", "ignore it", "pick the louder student"]'::jsonb,0,'Mediation guides students to agree.','original'),
('127.315.d.6.F',4,'A calm tone and neutral language during a conflict help to:','["end the lesson", "de-escalate the situation", "increase tension", "assign blame"]'::jsonb,1,'Calm adults lower tension.','original'),
('127.315.d.7.A',3,'Assessment is used in the learning process to:','["sort lunch trays", "rank teachers by height", "gather evidence of what students know and can do", "schedule buses"]'::jsonb,2,'Assessment informs teaching and learning.','original'),
('127.315.d.7.A',4,'An assessment given during learning to guide instruction is called:','["state ranking", "summative assessment", "placement test only", "formative assessment"]'::jsonb,3,'Formative checks guide next steps.','original'),
('127.315.d.7.B',3,'A good test question should:','["match the learning objective", "be as tricky as possible", "use confusing wording", "cover unrelated content"]'::jsonb,0,'Valid items measure the objective.','original'),
('127.315.d.7.B',4,'A rubric helps assess a project by:','["ranking students", "listing clear criteria and performance levels", "replacing the project", "hiding grading rules"]'::jsonb,1,'Rubrics make expectations explicit.','original'),
('127.315.d.7.C',3,'If 80 percent of students miss the same question, the teacher should most likely:','["remove the question from the book", "blame the students", "reteach the concept", "ignore the results"]'::jsonb,2,'Common errors signal a teaching need.','original'),
('127.315.d.7.C',4,'Item analysis of a test helps a teacher identify:','["parking needs", "attendance patterns only", "students'' heights", "questions or skills that many students missed"]'::jsonb,3,'Item analysis finds weak spots.','original'),
('127.315.d.7.D',3,'An exit ticket is a:','["quick check of understanding at the end of a lesson", "bus pass", "semester exam", "grade appeal"]'::jsonb,0,'Exit tickets are brief formative checks.','original'),
('127.315.d.7.D',4,'Observing students as they work and recording notes is a form of:','["state testing", "informal assessment", "lecture", "summative exam"]'::jsonb,1,'Observation provides ongoing evidence.','original'),
('127.315.d.7.E',3,'After a quiz shows students struggled with fractions, a teacher should:','["lower the quiz grades", "move on unchanged", "revise the next lessons to address fractions", "stop teaching math"]'::jsonb,2,'Data should change instruction.','original'),
('127.315.d.7.E',4,'Using assessment results to revise teaching is part of a cycle that includes planning, teaching, assessing, and:','["ignoring results", "ending", "repeating exactly", "reflecting and adjusting"]'::jsonb,3,'The cycle continues with improvement.','original'),
('127.315.d.8.A',3,'Schools reflect society when they:','["teach skills that communities and the workforce need", "exclude families", "ignore community needs", "avoid current issues"]'::jsonb,0,'Schools respond to community needs.','original'),
('127.315.d.8.A',4,'Changes in technology and the economy lead schools to add courses such as:','["no electives", "computer science and career-technical programs", "only penmanship", "only Latin"]'::jsonb,1,'Curricula evolve with society.','original'),
('127.315.d.8.B',3,'A new teacher can grow professionally by:','["avoiding feedback", "skipping training", "joining a professional organization and attending workshops", "working alone"]'::jsonb,2,'Professional networks support growth.','original'),
('127.315.d.8.B',4,'Education service centers in Texas provide teachers with:','["school lunches", "bus routes", "building permits", "training and instructional resources"]'::jsonb,3,'ESCs support districts and teachers.','original'),
('127.315.d.8.C',3,'A teacher works with a parent group to plan a family reading night. This is an example of:','["collaborating with stakeholders", "avoiding families", "working in isolation", "testing students"]'::jsonb,0,'Joint planning builds partnerships.','original'),
('127.315.d.8.C',4,'Collaboration between teachers and community agencies can help students by:','["delaying help", "connecting them to needed services", "duplicating tests", "removing support"]'::jsonb,1,'Agencies provide extra supports.','original'),
('127.315.d.9.A',3,'Technology supports instruction by:','["replacing teachers entirely", "removing the need for objectives", "providing tools for research, practice, and communication", "ending assessments"]'::jsonb,2,'Technology is a tool, not a replacement.','original'),
('127.315.d.9.A',4,'A teacher uses an online simulation of a science experiment that is too dangerous to do in class. This shows technology used to:','["replace the TEKS", "avoid planning", "cut instruction time", "extend learning beyond what is practical in class"]'::jsonb,3,'Simulations make impossible labs possible.','original'),
('127.315.d.9.B',3,'A graphing app is most appropriate for a lesson in:','["algebra", "lunchroom behavior", "penmanship", "fire safety"]'::jsonb,0,'Graphing tools fit math content.','original'),
('127.315.d.9.B',4,'A teacher chooses a grammar-checking tool for an English lesson because it:','["is the newest app", "supports the writing objective", "is popular with teens", "is free of charge only"]'::jsonb,1,'Tools should match the objective.','original'),
('127.315.d.9.C',3,'A teacher posts assignments and grades in an online learning management system. This is technology used for:','["social media posts only", "school lunches", "instruction, evaluation, and communication", "entertainment only"]'::jsonb,2,'LMS tools serve several functions.','original'),
('127.315.d.9.C',4,'Which is a responsible practice when using an online grade book?','["Post grades publicly", "Leave it open on the projector", "Share logins with students", "Use strong passwords and log out of shared computers"]'::jsonb,3,'Protect student data.','original'),
('127.315.d.10.A',3,'A teacher who maintains confidentiality about student records is practicing:','["professional ethics", "favoritism", "negligence", "gossip"]'::jsonb,0,'Confidentiality is an ethical duty.','original'),
('127.315.d.10.A',4,'Arriving prepared, meeting deadlines, and treating colleagues respectfully are examples of:','["personal preference", "professional conduct", "optional behavior", "unfair practice"]'::jsonb,1,'Professionalism shows in daily habits.','original'),
('127.315.d.10.B',3,'In Texas, the Educators'' Code of Ethics is enforced by the:','["Texas Lottery Commission", "Texas Railroad Commission", "State Board for Educator Certification", "Texas Parks and Wildlife Department"]'::jsonb,2,'SBEC sets and enforces educator standards.','original'),
('127.315.d.10.B',4,'The Educators'' Code of Ethics requires teachers to deal fairly with:','["only high achievers", "only favorite students", "only their own children", "all students without discrimination"]'::jsonb,3,'Fair treatment is required.','original'),
('127.315.d.10.C',3,'A student offers a teacher an expensive gift just before report cards. The ethical response is to:','["politely decline and follow district policy", "ask for more", "accept and change the grade", "accept it secretly"]'::jsonb,0,'Gifts can compromise fairness.','original'),
('127.315.d.10.C',4,'A colleague shares a student''s grades in a public hallway. The best response is to:','["join in", "remind the colleague of student privacy laws and report if it continues", "post them online", "ignore the law"]'::jsonb,1,'Privacy protections apply.','original'),
('127.315.d.10.D',3,'A teacher who violates the Educators'' Code of Ethics may lose:','["their school locker", "their lunch period", "their teaching certificate", "their parking spot"]'::jsonb,2,'Serious violations can end a career.','original'),
('127.315.d.10.D',4,'Complying with the Code of Ethics helps a school by:','["limiting learning", "reducing safety", "removing accountability", "protecting students and maintaining public trust"]'::jsonb,3,'Ethical staff protect children.','original'),
('127.315.d.11.A',3,'A student teacher at an elementary campus leads a small reading group. This is applying instructional strategies in:','["a local educational setting", "a laboratory only", "a hospital", "a courtroom"]'::jsonb,0,'Practicum happens in real schools.','original'),
('127.315.d.11.A',4,'Before leading a lesson during practicum, a student should confirm the plan with the:','["lunch cashier", "cooperating teacher", "bus driver", "visitor"]'::jsonb,1,'The host teacher supervises.','original'),
('127.315.d.11.B',3,'A practicum journal helps a student teacher:','["avoid feedback", "hide mistakes", "record and reflect on instructional experiences", "replace lesson plans"]'::jsonb,2,'Journals build reflective practice.','original'),
('127.315.d.11.B',4,'Reflection after a lesson is most useful when it identifies:','["only blame", "nothing specific", "only what went well", "what worked, what did not, and what to change"]'::jsonb,3,'Specific reflection leads to improvement.','original'),
('127.315.d.12.A',3,'Which item belongs in a teaching portfolio?','["A lesson plan and a reflection on how it went", "A game score", "A grocery receipt", "A restaurant menu"]'::jsonb,0,'Portfolios show professional work.','original'),
('127.315.d.12.A',4,'A student teacher adds a letter from a cooperating teacher to the portfolio because it:','["shows personal hobbies", "gives evidence of professional skills from an observer", "lists school lunches", "replaces the resume"]'::jsonb,1,'Third-party evidence adds credibility.','original'),
('127.315.d.12.B',3,'When presenting a teaching portfolio to a principal, a candidate should:','["read each page silently", "skip the best items", "highlight evidence of skills with confident, organized delivery", "apologize for the work"]'::jsonb,2,'Confidence and organization impress.','original'),
('127.315.d.12.B',4,'After a portfolio interview, a candidate can follow up by:','["posting complaints", "avoiding contact", "criticizing the panel", "sending a thank-you note"]'::jsonb,3,'Courtesy leaves a good impression.','original'),
('127.315.d.13.A',3,'Feedback helps learning because it:','["shows students what to keep doing and what to improve", "stops all effort", "embarrasses students", "only assigns grades"]'::jsonb,0,'Feedback guides next steps.','original'),
('127.315.d.13.A',4,'Which feedback is most useful?','["This is bad.", "Your thesis is clear; add evidence in paragraph two.", "Good job.", "Try harder."]'::jsonb,1,'Specific comments tell students what to do.','original'),
('127.315.d.13.B',3,'A teacher praises a student''s effort on a hard problem. This feedback motivates by:','["ending effort", "comparing students", "reinforcing persistence", "lowering expectations"]'::jsonb,2,'Effort praise encourages persistence.','original'),
('127.315.d.13.B',4,'Motivating feedback focuses on:','["other students'' grades", "luck", "the student''s personality", "specific actions the student can control"]'::jsonb,3,'Controllable actions empower students.','original'),
('127.315.d.13.C',3,'A checklist gives student feedback by:','["showing which required parts were completed", "ranking students", "replacing the assignment", "hiding criteria"]'::jsonb,0,'Checklists make progress visible.','original'),
('127.315.d.13.C',4,'One-on-one conferences provide feedback that is:','["delayed for weeks", "personalized and immediate", "identical for all", "anonymous"]'::jsonb,1,'Conferences tailor feedback.','original'),
('127.315.d.13.D',3,'A teacher receives a critique from an observer. A professional response is to:','["argue", "ignore it", "listen and consider how to improve", "blame students"]'::jsonb,2,'Openness to feedback drives growth.','original'),
('127.315.d.13.D',4,'After receiving feedback, a teacher sets a goal and tries a new strategy. This demonstrates:','["avoidance", "stagnation", "defensiveness", "reflective practice"]'::jsonb,3,'Reflective teachers act on feedback.','original'),
('127.315.d.13.E',3,'Which question promotes deeper discussion?','["Why do you think the author chose this ending?", "Is this book blue?", "Do you like it, yes or no?", "What page are we on?"]'::jsonb,0,'Open-ended why questions prompt analysis.','original'),
('127.315.d.13.E',4,'Asking students to explain their reasoning after they answer helps develop:','["guessing", "critical thinking", "speed only", "silent compliance"]'::jsonb,1,'Explaining reveals and builds thinking.','original'),
('127.315.d.14.A',3,'IDEA stands for the:','["International Developmental Education Alliance", "Inclusive District Education Act", "Individuals with Disabilities Education Act", "Instructional Data Evaluation Association"]'::jsonb,2,'IDEA is the federal special education law.','original'),
('127.315.d.14.A',4,'Section 504 of the Rehabilitation Act protects students who have:','["high test scores", "a perfect attendance record", "a late bus", "a disability that substantially limits a major life activity"]'::jsonb,3,'Section 504 covers disabilities that limit life activities.','original'),
('127.315.d.14.B',3,'An IEP is written for a student who:','["qualifies for special education services", "has a low grade once", "is new to the school", "needs a bus pass"]'::jsonb,0,'IEPs serve identified students.','original'),
('127.315.d.14.B',4,'Which is a required component of an IEP?','["A club list", "Measurable annual goals", "A lunch preference", "A seating chart"]'::jsonb,1,'IEPs include measurable goals.','original')
