('127.315.d.14.C',3,'A Section 504 Plan typically provides:','["a separate school", "automatic passing grades", "accommodations that give equal access to learning", "a different curriculum for all"]'::jsonb,2,'504 plans ensure access.','original'),
('127.315.d.14.C',4,'A student with a 504 Plan for ADHD might receive:','["removal from class", "a different diploma", "a lower grade level", "preferential seating and extra time"]'::jsonb,3,'Accommodations remove barriers.','original'),
