('127.343.d.1.B',3,'Which quality is most important for an early childhood educator?','["Indifference", "Impatience", "Patience and responsiveness to children", "Rigid control"]'::jsonb,2,'Young children need responsive adults.','original'),
('127.343.d.1.B',4,'An early childhood professional who adapts activities to each child''s pace shows:','["rigidity", "disinterest", "favoritism", "flexibility and respect for individual needs"]'::jsonb,3,'Individualization is a mark of quality.','original'),
('127.343.d.1.C',3,'A written statement of an early childhood teacher''s beliefs about how children learn is a:','["philosophy statement", "lesson sequence", "budget", "fire drill plan"]'::jsonb,0,'Philosophy statements express beliefs.','original'),
