('127.345.d.10.A',3,'A teacher who gives every student equal chances to participate is demonstrating:','["bias", "favoritism", "exclusion", "fairness"]'::jsonb,3,'Equity of participation is professional.','original'),
('127.345.d.10.A',4,'Which behavior shows professionalism on social media?','["Keeping posts appropriate and not sharing student information", "Posting student grades", "Sharing rumors", "Complaining about students"]'::jsonb,0,'Professionals protect privacy.','original'),
('127.345.d.10.B',3,'The Texas Educators'' Code of Ethics sets standards for:','["school menus", "professional conduct of educators", "sports rules", "bus drivers only"]'::jsonb,1,'The code governs educator conduct.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_55_v1'
from (values
('127.345.d.10.B',4,'Teachers are mandated reporters, meaning they must report:','["all absences", "all grades", "suspected abuse or neglect", "all discipline"]'::jsonb,2,'Mandated reporters protect children.','original'),
('127.345.d.10.C',3,'A teacher is offered a tutoring fee to give a student a better grade. Ethical practice is to:','["hide it", "accept it", "ask for more", "refuse and follow district policy"]'::jsonb,3,'Grades must reflect merit.','original'),
('127.345.d.10.C',4,'A teacher finds out a colleague is sharing test questions early with some students. The ethical response is to:','["report the matter to administration", "tell students", "ignore it", "join in"]'::jsonb,0,'Test security is an ethical duty.','original'),
('127.345.d.10.D',3,'Non-compliance with the Code of Ethics can result in:','["a school award", "sanctions such as certificate suspension or revocation", "a bonus", "a longer break"]'::jsonb,1,'Sanctions follow serious violations.','original'),
('127.345.d.10.D',4,'A teacher''s certificate may be revoked for:','["using a new textbook", "arriving one minute late once", "serious misconduct such as an improper relationship with a student", "changing a bulletin board"]'::jsonb,2,'Serious violations carry serious penalties.','original'),
('127.345.d.11.A',3,'Which is a resource for teachers'' professional development?','["Cafeteria menus", "Bus routes", "Parking permits", "Education service center workshops"]'::jsonb,3,'ESCs offer training.','original'),
('127.345.d.11.A',4,'Professional learning communities help teachers by:','["sharing practices and analyzing student data together", "working alone", "avoiding feedback", "hiding results"]'::jsonb,0,'Collaboration improves practice.','original'),
('127.345.d.11.B',3,'A teacher who reads research and tries new strategies is demonstrating:','["stagnation", "ongoing professional growth", "avoidance", "complacency"]'::jsonb,1,'Growth is continuous.','original'),
('127.345.d.11.B',4,'Attending a conference and then sharing what was learned with colleagues:','["hides learning", "wastes time", "extends the benefit of the training", "reduces collaboration"]'::jsonb,2,'Sharing multiplies impact.','original'),
('127.345.d.11.C',3,'A professional growth plan should include:','["only complaints", "vague wishes", "no deadlines", "specific goals, actions, and timelines"]'::jsonb,3,'Specific plans are actionable.','original'),
('127.345.d.11.C',4,'A teacher whose data show weak writing results sets a goal to learn writing workshop methods. This goal is:','["tied to student needs", "random", "unrelated to teaching", "personal only"]'::jsonb,0,'Goals should address student needs.','original'),
('127.345.d.12.A',3,'During a practicum, a student teacher uses a think-pair-share with a class. This applies:','["a school rule", "an instructional strategy in a real classroom", "a bus plan", "a lunch routine"]'::jsonb,1,'Practicum applies strategies.','original'),
('127.345.d.12.A',4,'A practicum student should seek feedback after teaching from the:','["visitors", "janitor", "cooperating teacher", "cafeteria staff"]'::jsonb,2,'The cooperating teacher observes and advises.','original'),
('127.345.d.12.B',3,'A reflective journal entry should describe what happened, why it mattered, and:','["weather forecasts", "lunch choices", "grades of friends", "what the teacher will do next"]'::jsonb,3,'Reflection ends with action.','original'),
('127.345.d.12.B',4,'Keeping a log of practicum hours and activities supports:','["accountability and portfolio evidence", "avoidance", "errors", "secrecy"]'::jsonb,0,'Logs prove participation.','original'),
('127.345.d.13.A',3,'Evidence that shows a student''s technical skills in teaching could be:','["a vacation photo", "an observation report completed by a supervising teacher", "a concert ticket", "a gift receipt"]'::jsonb,1,'Observation reports document skill.','original'),
('127.345.d.13.A',4,'Artifacts in a portfolio should be:','["unrelated", "random and unlabeled", "relevant, organized, and labeled", "outdated only"]'::jsonb,2,'Good artifacts are curated.','original'),
('127.345.d.13.B',3,'Updating a teaching resume to include practicum experience shows:','["old information", "irrelevant details", "hobbies only", "recent and relevant experience"]'::jsonb,3,'Resumes should reflect current experience.','original'),
('127.345.d.13.B',4,'A teaching portfolio''s philosophy statement should be:','["revised as beliefs and experience grow", "never changed", "copied from others", "left blank"]'::jsonb,0,'Philosophies evolve.','original'),
('127.345.d.13.C',3,'A professional portfolio presentation to a hiring panel is an opportunity to:','["hide work", "demonstrate qualifications and communication skills", "read silently", "avoid questions"]'::jsonb,1,'Presentations showcase skills.','original'),
('127.345.d.13.C',4,'Preparing talking points before a portfolio presentation helps a candidate:','["skip examples", "avoid eye contact", "stay organized and confident", "sound scripted forever"]'::jsonb,2,'Preparation builds confidence.','original'),
('127.346.d.2',3,'A teacher notices students struggle with a lab routine. Advanced problem solving involves:','["assigning blame", "skipping labs", "repeating the same method", "diagnosing the cause, testing a solution, and checking the results"]'::jsonb,3,'Effective problem solving is systematic.','original'),
('127.346.d.2',4,'A problem-solving cycle ends with:','["evaluating the solution and refining it", "starting over blindly", "stopping at the first idea", "ignoring results"]'::jsonb,0,'Evaluation completes the cycle.','original'),
('127.346.d.1.A',3,'A teacher uses a steady voice, clear words, and open body posture when addressing a class. This shows consistent:','["silent behavior", "verbal and non-verbal communication", "written-only messaging", "avoidance"]'::jsonb,1,'Words and body language align.','original'),
('127.346.d.1.A',4,'Which tone best supports clear classroom directions?','["Mumbling", "Shouting", "Calm and firm", "Sarcastic"]'::jsonb,2,'A calm, firm tone communicates authority respectfully.','original'),
('127.346.d.1.B',3,'An effective formal presentation to a school committee has:','["unrelated visuals", "no structure", "only anecdotes", "a clear opening, supporting evidence, and a conclusion"]'::jsonb,3,'Structure persuades audiences.','original'),
('127.346.d.1.B',4,'An informal presentation, such as a quick update at a team meeting, is usually:','["shorter and more conversational", "a legal filing", "a state exam", "a written report only"]'::jsonb,0,'Informal talks are brief and casual.','original'),
('127.346.d.1.C',3,'A teacher reviews quiz results and explains the trends to colleagues. This is:','["hiding results", "analyzing and communicating data", "ignoring evidence", "guessing"]'::jsonb,1,'Data become useful when shared.','original'),
('127.346.d.1.C',4,'When communicating data to others, a clear graph is useful because it:','["hides information", "confuses readers", "makes patterns easy to see", "replaces explanation"]'::jsonb,2,'Visuals clarify trends.','original'),
('127.346.d.1.D',3,'A student teacher asks, Do you mean the rubric needs more detail? This active-listening move is:','["judging", "interrupting", "ending the talk", "asking a clarifying question"]'::jsonb,3,'Clarifying prevents misunderstanding.','original'),
('127.346.d.1.D',4,'Active listening helps obtain accurate information because it:','["confirms understanding before acting", "adds confusion", "delays decisions", "replaces research"]'::jsonb,0,'Confirming prevents errors.','original'),
('127.346.d.3.A',3,'A teacher who finishes assigned duties and volunteers to help others shows:','["avoidance", "a productive work ethic", "entitlement", "laziness"]'::jsonb,1,'Initiative marks a strong work ethic.','original'),
('127.346.d.3.B',3,'A practicum student discovers an error in the grade book that benefits a friend. Integrity means:','["helping hide it", "adding to it", "reporting and correcting the error", "leaving it alone"]'::jsonb,2,'Honesty requires correction.','original'),
('127.346.d.3.A',4,'Punctuality and preparedness are signs of:','["disorder", "disrespect", "indifference", "reliability"]'::jsonb,3,'Reliable people are on time and ready.','original'),
('127.346.d.3.B',4,'Honesty in reporting practicum hours means:','["recording only the hours actually worked", "copying others'' logs", "rounding up", "estimating high"]'::jsonb,0,'Accurate records show integrity.','original'),
('127.346.d.3.C',3,'A district''s acceptable-use policy says students and staff must:','["visit any site", "use school technology for appropriate purposes", "share passwords", "download anything"]'::jsonb,1,'AUPs set boundaries for technology.','original'),
('127.346.d.3.C',4,'Proper email etiquette for a teacher includes:','["writing in all caps", "using slang", "using a professional tone and greeting", "omitting a subject"]'::jsonb,2,'Professional email is polite and clear.','original'),
('127.346.d.3.D',3,'A teacher follows FERPA by:','["sharing records freely", "leaving records open", "posting grades publicly", "protecting student education records"]'::jsonb,3,'FERPA protects privacy of records.','original'),
('127.346.d.3.D',4,'Following district policy on field trips, such as signed permission slips, shows:','["compliance with rules and regulations", "optional practice", "guessing", "ignoring policy"]'::jsonb,0,'Compliance protects students and staff.','original'),
('127.346.d.4.A',3,'With increased fluency, a student teacher can adjust a lesson when:','["lunch arrives", "students show they have not understood", "a visitor leaves", "a bell rings"]'::jsonb,1,'Fluent teachers respond to evidence.','original'),
